if FRAME_COUNT > 1 and DURATION_SECONDS > 0.0:
    # Play back at the same rate the mechanism actually runs.
    scene.render.fps = 60
    scene.render.fps_base = 60.0 * DURATION_SECONDS / (FRAME_COUNT - 1)


def mm(v):
    return v / 1000.0


def make_joint(name, is_anchor):
    bpy.ops.object.empty_add(
        type='PLAIN_AXES' if is_anchor else 'SPHERE',
        radius=mm(JOINT_MARKER_RADIUS_MM), location=(0.0, 0.0, 0.0))
    obj = bpy.context.object
    obj.name = name
    return obj


def make_rod(name):
    # Unit-depth cylinder: its length is set per frame via scale.z,
    # which also lets variable-length links animate correctly.
    bpy.ops.mesh.primitive_cylinder_add(radius=mm(ROD_RADIUS_MM), depth=1.0,
                                        location=(0.0, 0.0, 0.0))
    obj = bpy.context.object
    obj.name = name
    obj.rotation_mode = 'QUATERNION'
    return obj


def make_cam(name, profile, roller_radius_mm):
    # A solid prism swept from the cam's real surface outline: bottom
    # ring, top ring, a quad per edge, and an n-gon cap at each end.
    half = mm(CAM_THICKNESS_MM) / 2.0
    n = len(profile)
    verts = [(mm(x), mm(y), -half) for (x, y) in profile]
    verts += [(mm(x), mm(y), half) for (x, y) in profile]
    faces = [(i, (i + 1) % n, n + ((i + 1) % n), n + i) for i in range(n)]
    faces.append(tuple(reversed(range(n))))
    faces.append(tuple(range(n, 2 * n)))
    mesh = bpy.data.meshes.new(name)
    mesh.from_pydata(verts, [], faces)
    mesh.validate()
    mesh.update()
    obj = bpy.data.objects.new(name, mesh)
    bpy.context.scene.collection.objects.link(obj)
    obj.rotation_mode = 'XYZ'
    return obj


def make_roller(name, radius_mm):
    bpy.ops.mesh.primitive_cylinder_add(radius=mm(radius_mm),
                                        depth=mm(CAM_THICKNESS_MM),
                                        location=(0.0, 0.0, 0.0))
    obj = bpy.context.object
    obj.name = name
    return obj


def make_rail(name):
    bpy.ops.mesh.primitive_cylinder_add(radius=mm(ROD_RADIUS_MM) * 0.55, depth=1.0,
                                        location=(0.0, 0.0, 0.0))
    obj = bpy.context.object
    obj.name = name
    obj.rotation_mode = 'QUATERNION'
    return obj


def make_disc(name, radius_mm):
    # A gear or Geneva wheel: a flat disc that turns with its body.
    bpy.ops.mesh.primitive_cylinder_add(radius=mm(radius_mm),
                                        depth=mm(ROD_RADIUS_MM) * 1.2,
                                        location=(0.0, 0.0, 0.0))
    obj = bpy.context.object
    obj.name = name
    obj.rotation_mode = 'XYZ'
    return obj


joints = [make_joint(name, is_anchor) for (name, is_anchor) in JOINTS]
rods = [(make_rod(name), i, j) for (name, i, j) in RODS]
cams = [(make_cam(name, profile, roller), center, follower)
        for (name, center, follower, roller, profile) in CAMS]
rollers = [(make_roller(name + '_Roller', roller), follower)
           for (name, _c, follower, roller, _p) in CAMS if follower >= 0]
rails = [(make_rail(name), i, j) for (name, i, j) in RAILS]
discs = [(make_disc(name, r), c, ref) for (name, c, ref, r) in DISCS]


for frame_index, positions in enumerate(FRAMES):
    frame = frame_index + 1
    angles = CAM_ANGLES[frame_index] if frame_index < len(CAM_ANGLES) else []
    for obj, (x, y) in zip(joints, positions):
        obj.location = (mm(x), mm(y), 0.0)
        obj.keyframe_insert('location', frame=frame)
    for cam_index, (obj, center, _follower) in enumerate(cams):
        cx, cy = positions[center]
        obj.location = (mm(cx), mm(cy), 0.0)
        obj.rotation_euler = (0.0, 0.0, angles[cam_index] if cam_index < len(angles) else 0.0)
        obj.keyframe_insert('location', frame=frame)
        obj.keyframe_insert('rotation_euler', frame=frame)
    for obj, follower in rollers:
        fx, fy = positions[follower]
        obj.location = (mm(fx), mm(fy), 0.0)
        obj.keyframe_insert('location', frame=frame)
    for obj, i, j in rails:
        p0 = mathutils.Vector((mm(positions[i][0]), mm(positions[i][1]), 0.0))
        p1 = mathutils.Vector((mm(positions[j][0]), mm(positions[j][1]), 0.0))
        direction = p1 - p0
        length = direction.length
        obj.location = (p0 + p1) / 2.0
        if length > 1e-12:
            obj.rotation_quaternion = direction.to_track_quat('Z', 'Y')
        obj.scale = (1.0, 1.0, max(length, 1e-9))
        obj.keyframe_insert('location', frame=frame)
        obj.keyframe_insert('rotation_quaternion', frame=frame)
        obj.keyframe_insert('scale', frame=frame)
    for obj, c, ref in discs:
        cx, cy = positions[c]
        rx, ry = positions[ref]
        obj.location = (mm(cx), mm(cy), 0.0)
        obj.rotation_euler = (0.0, 0.0, math.atan2(ry - cy, rx - cx))
        obj.keyframe_insert('location', frame=frame)
        obj.keyframe_insert('rotation_euler', frame=frame)
    for obj, i, j in rods:
        p0 = mathutils.Vector((mm(positions[i][0]), mm(positions[i][1]), 0.0))
        p1 = mathutils.Vector((mm(positions[j][0]), mm(positions[j][1]), 0.0))
        direction = p1 - p0
        length = direction.length
        obj.location = (p0 + p1) / 2.0
        if length > 1e-12:
            obj.rotation_quaternion = direction.to_track_quat('Z', 'Y')
        obj.scale = (1.0, 1.0, max(length, 1e-9))
        obj.keyframe_insert('location', frame=frame)
        obj.keyframe_insert('rotation_quaternion', frame=frame)
        obj.keyframe_insert('scale', frame=frame)

def iter_fcurves(action):
    # Blender <4.4 exposes action.fcurves directly; 4.4+ moved them
    # into slotted actions (layers -> strips -> channelbags).
    fcurves = getattr(action, 'fcurves', None)
    if fcurves is not None:
        for fcurve in fcurves:
            yield fcurve
        return
    for layer in getattr(action, 'layers', []):
        for strip in getattr(layer, 'strips', []):
            for channelbag in getattr(strip, 'channelbags', []):
                for fcurve in channelbag.fcurves:
                    yield fcurve


# Constant-speed motion should not ease in and out between samples.
# The motion is already baked into the keyframes, so treat this as a
# nicety: never let an API change here break the whole import.
try:
    animated = (joints + [rod for (rod, _i, _j) in rods]
               + [cam for (cam, _c, _f) in cams] + [r for (r, _f) in rollers]
               + [r for (r, _i, _j) in rails] + [d for (d, _c, _r) in discs])
    for obj in animated:
        action = obj.animation_data.action if obj.animation_data else None
        if action is None:
            continue
        for fcurve in iter_fcurves(action):
            for kp in fcurve.keyframe_points:
                kp.interpolation = 'LINEAR'
except Exception as exc:
    print('Linkage Design: could not set linear interpolation (%s); '
          'the animation is still correct.' % exc)

scene.frame_set(1)
print('Linkage Design: built %d joints, %d rods, %d rails, %d discs, '
      '%d cams, %d frames.'
      % (len(joints), len(rods), len(rails), len(discs), len(cams), FRAME_COUNT))
